def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    n, p = X.shape; ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1))
    if len(labs) > 1:
        st = np.array(feats.stratum)
        S = np.column_stack([S] + [(st == l).astype(float) for l in labs[1:]])

    def ll(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    def mk(cols, prods=()):
        parts = [S] + [X[:, [c]] for c in cols] + [(X[:, a] * X[:, b])[:, None] for a, b in prods]
        return np.column_stack(parts)

    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    alpha = 0.05 / p
    sel = []; base = ll(mk(sel))
    while len(sel) < MAX_DRIVERS:
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            l = ll(mk(sel + [j]))
            if best is None or l > best[0]: best = (l, j)
        if best is None: break
        pv = stats.chi2.sf(2 * (best[0] - base), 1)
        if pv > alpha: break
        sel.append(best[1]); base = best[0]
    changed = True
    while changed and len(sel) > 1:
        changed = False
        full = ll(mk(sel))
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (full - ll(mk(rest))), 1) > alpha:
                sel = rest; changed = True; break
    prods = []
    npair = p * (p - 1) / 2
    cand = []
    for a in range(p):
        for b in range(a + 1, p):
            if abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b})
            l0 = ll(mk(mains)); l1 = ll(mk(mains, [(a, b)]))
            pv = stats.chi2.sf(2 * (l1 - l0), 1)
            if pv < 0.002 / npair: cand.append((pv, a, b))
    cand.sort()
    for pv, a, b in cand[:1]:
        prods.append((a, b))
    drivers = list(sel)
    for a, b in prods:
        for c in (a, b):
            if c not in drivers: drivers.append(c)
    drivers = drivers[:MAX_DRIVERS]
    cols = sorted(set(sel) | {c for pr in prods for c in pr})
    return Design(drivers=tuple(ids[j] for j in drivers), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

